<template><div class="table"><table><thead><tr><th>Réparateur　⌃</th><th>Téléphone　⌃</th><th>Catégories / Spécialités　⌃</th><th>Zones de couverture　⌃</th><th>Statut pro　⌃</th><th>Actions　⌃</th></tr></thead><tbody><tr v-for="r in reparateurs" :key="r.id"><td class="pro"><img :src="r.image"><span><b>{{r.name}}</b><small>ID: {{r.id}}</small></span></td><td>{{r.phone}}</td><td class="list"><span v-for="x in r.specialties" :key="x">▣　{{x}}</span></td><td class="list"><span v-for="x in r.zones" :key="x">●　{{x}}</span></td><td><mark :class="r.status.replaceAll(' ','-')">{{r.status}}</mark></td><td class="actions"><button @click="$emit('verify',r)">⌕ Vérifier</button><button :class="{unlock:r.estBloque}" @click="$emit('block',r)">{{ r.estBloque ? '▣ Débloquer' : '╱ Bloquer' }}</button></td></tr></tbody></table></div></template>
<script setup>defineProps({reparateurs:{type:Array,default:()=>[]}});defineEmits(['verify','block'])</script>
<style scoped>.table{overflow:hidden;border:1px solid #ddebfb;border-radius:9px}table{width:100%;border-collapse:collapse;table-layout:fixed}th{text-align:left;height:49px;padding:10px 12px;background:#e8f6f2;text-transform:uppercase;color:#1850a3;font-size:10px}th:nth-child(1){width:18%}th:nth-child(2){width:13%}th:nth-child(3){width:19%}th:nth-child(4){width:15%}th:nth-child(5){width:14%}th:last-child{width:21%}td{height:86px;padding:10px 12px;border-bottom:1px solid #dfeefa;color:#245bb2;font-size:12px;overflow-wrap:anywhere}.pro{display:flex;align-items:center;gap:9px;color:#174b50}.pro img{width:48px;height:48px;flex:0 0 auto;border-radius:50%;object-fit:cover}.pro b,.list span{display:block}.pro small{display:block;width:max-content;max-width:100%;background:#e5f4f0;border-radius:12px;padding:3px 7px;color:#4375c9;margin-top:5px;font-size:10px}.list{line-height:1.65}.list span{display:block}mark{display:inline-block;border-radius:20px;padding:7px 9px;background:#fff1d8;color:#ee9000;font-size:11px}.Certifié-Pro{background:#dcf8ed;color:#00a879}.Compte-bloqué{background:#ffe1e6;color:#f3344f}.actions{white-space:nowrap}.actions button{box-sizing:border-box;width:96px;height:34px;padding:8px 6px;border:1px solid #77aeff;border-radius:6px;background:#fff;color:#087f70;font-size:11px}.actions button+button{margin-left:5px;border-color:#ff8497;color:#f6334d}.actions .unlock{border-color:#69d9ad;color:#00a879}@media(max-width:900px){th:nth-child(2),td:nth-child(2){display:none}th:nth-child(1){width:24%}th:nth-child(3){width:23%}th:nth-child(4){width:18%}th:nth-child(5){width:16%}th:last-child{width:19%}.actions button{display:block;width:100%;font-size:10px}.actions button+button{margin:5px 0 0}}@media(max-width:620px){th:nth-child(3),td:nth-child(3),th:nth-child(4),td:nth-child(4){display:none}th:nth-child(1){width:42%}th:nth-child(5){width:25%}th:last-child{width:33%}.pro img{width:40px;height:40px}td{padding:9px 7px}.actions button{padding:7px 4px}}</style>
